const results = $input.item.json.result;
if (!results || results.length === 0) {
  return [{ json: { chunks: [], has_results: false, query: $('Chat Trigger').item.json.chatInput } }];
}
const chunks = results.map(r => ({
  text: r.payload.text,
  title: r.payload.title,
  score: r.score,
  chunk_index: r.payload.chunk_index,
  ingested_at: r.payload.ingested_at
}));
return [{ json: { chunks, has_results: true, query: $('Chat Trigger').item.json.chatInput } }];

const raw1 = $('Generate Answer').item.json.text.replace(/```json|```/g,'').trim();
const raw2 = $input.item.json.text.replace(/```json|```/g,'').trim();
const answer = JSON.parse(raw1);
const verified = JSON.parse(raw2);
const chunks = $('Extract Retrieved Chunks').item.json.chunks;
const sourceList = chunks.map((c,i) => `[Source ${i+1}] ${c.title} (relevance: ${Math.round(c.score*100)}%)`).join('
');
const final = `${verified.verified_answer}

---
**Sources:**
${sourceList}

**Verification:** ${verified.verification_summary}
**Confidence:** ${answer.confidence}`;
return [{ json: { response: final, hallucination_detected: verified.hallucination_detected, sources: chunks.length } }];
